"""Deep semantic map of FMZ JavaScript strategy 教学策略TCI策略麦语言移植.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '教学策略TCI策略麦语言移植.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', '_C(', 'Sleep(', 'GetRecords']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.']
ORIGINAL_JAVASCRIPT = '/*backtest\nstart: 2019-05-01 00:00:00\nend: 2019-11-12 00:00:00\nperiod: 1d\nexchanges: [{"eid":"Futures_OKCoin","currency":"BTC_USD"}]\n*/\n\n/* 原版麦语言策略\nN1:=10;\nN2:=21;\nAP:=(HIGH+LOW+CLOSE)/3;\nESA:=EMA(AP,N1);\nD:=EMA(ABS(AP-ESA),N1);\nCI:=(AP-ESA)/(0.015*D);\nTCI:=EMA(CI,N2);\nWT1:TCI;\nWT2:SMA(WT1,4,1);\nAA:=CROSS(WT1,WT2);\nBB:=CROSSDOWN(WT1,WT2);\nREF(AA,1),BPK;\nREF(BB,1),SPK;\n*/\n\n// 全局变量\nvar IDLE = 0\nvar LONG = 1\nvar SHORT = 2\nvar OPENLONG = 3\nvar OPENSHORT = 4\nvar COVERLONG = 5\nvar COVERSHORT = 6  \n\nvar BREAK = 9\nvar SHOCK = 10  \n\nvar _State = IDLE\nvar Amount = 1                 // 记录持仓数量\nvar TradeInterval = 500        // 轮询间隔\nvar PriceTick = 1              // 价格一跳\nvar Point = 5                  // 滑价点数\nvar Symbol = "quarter"  \n\n// 临时参数\nvar N1 = 10\nvar N2 = 21\n\nfunction CalcAP (r) {   // AP:=(HIGH+LOW+CLOSE)/3;\n    var arrAP = []\n\n    for (var i = 0; i < r.length; i++) {\n        v = (r[i].High + r[i].Low + r[i].Close) / 3\n        arrAP.push(v)\n    }\n\n    return arrAP\n}\n\nfunction CalcESA (ap, n1) {   // ESA:=EMA(AP,N1);\n    if (ap.length <= n1) {\n        return false\n    }\n\n    return TA.EMA(ap, n1)\n}\n\nfunction CalcD (ap, esa, n1) {    // D:=EMA(ABS(AP-ESA),N1);\n    var arrABS_APminusESA = []\n    if (ap.length != esa.length) {\n        throw "ap.length != esa.length"\n    }\n\n    for (var i = 0; i < ap.length; i++) {\n        if (ap[i] && esa[i] && !isNaN(ap[i]) && !isNaN(esa[i])) {\n            v = Math.abs(ap[i] - esa[i])\n            arrABS_APminusESA.push(v)\n        } else {\n            arrABS_APminusESA.push(NaN)\n        }\n    }\n\n    if (arrABS_APminusESA.length <= n1) {\n        return false\n    }\n\n    return TA.EMA(arrABS_APminusESA, n1)\n}\n\nfunction CalcCI (ap, esa, d) {    // CI:=(AP-ESA)/(0.015*D);\n    var arrCI = []\n    if (ap.length != esa.length || ap.length != d.length) {\n        throw "ap.length != esa.length || ap.length != d.length"\n    }\n    for (var i = 0; i < ap.length; i++) {\n        if (ap[i] && esa[i] && d[i] && !isNaN(ap[i]) && !isNaN(esa[i]) && !isNaN(d[i])) {\n            v = (ap[i] - esa[i]) / (0.015 * d[i])\n            arrCI.push(v)\n        } else {\n            arrCI.push(NaN)\n        }\n    }\n\n    if (arrCI.length == 0) {\n        return false\n    }\n\n    return arrCI\n}\n\nfunction CalcTCI (ci, n2) {   // TCI:=EMA(CI,N2);\n    if (ci.length <= n2) {\n        return false\n    }\n\n    return TA.EMA(ci, n2)\n}\n\nfunction SMA (arr, n, m) {\n    var sma = []\n    var currSMA = null\n    for (var i = 0; i < arr.length; i++) {\n        if (arr[i] && !isNaN(arr[i])) {\n            if (!currSMA) {\n                currSMA = arr[i]\n                sma.push(currSMA)\n                continue\n            }\n\n            // [M*C2+(N-M)*S1]/N\n            currSMA = (m * arr[i] + (n - m) * currSMA) / n\n            sma.push(currSMA)\n        } else {\n            sma.push(NaN)\n        }\n    }\n\n    return sma\n}\n\nfunction CalcWT2 (wt1) {    // WT2:SMA(WT1,4,1);\n    if (wt1.length <= 4) {\n        return false \n    }\n\n    return SMA(wt1, 4, 1)\n}\n\nvar isOK = true\nvar preTime = 0\nfunction OnTick(){\n    // 驱动策略的行情处理部分\n    var records = _C(exchange.GetRecords)\n    if (records[records.length - 1].Time == preTime) {\n        if (isOK) {\n            Sleep(500)\n            return \n        }\n    } else {\n        preTime = records[records.length - 1].Time\n    }\n\n    // 计算指标\n    // AP\n    var ap = CalcAP(records)\n\n    // ESA\n    var esa = CalcESA(ap, N1)\n    if (!esa) {\n        return \n    }\n\n    // D\n    var d = CalcD(ap, esa, N1)\n    if (!d) {\n        return \n    }\n\n    // CI\n    var ci = CalcCI(ap, esa, d)\n    if (!ci) {\n        return \n    }\n\n    // TCI\n    var tci = CalcTCI(ci, N2)\n    if (!tci) {\n        return \n    }\n\n    // WT1\n    var wt1 = tci\n\n    // WT2 \n    var wt2 = CalcWT2(wt1)\n    if (!wt2) {\n        return \n    }\n\n    // 交易信号触发处理部分\n    /*\n    AA:=CROSS(WT1,WT2);\n    BB:=CROSSDOWN(WT1,WT2);\n    REF(AA,1),BPK;\n    REF(BB,1),SPK;\n    */\n    if (wt1.length < 3 || wt2.length < 3) {\n        return \n    }\n\n    $.PlotLine("wt1", wt1[wt1.length - 2], records[records.length - 2].Time)\n    $.PlotLine("wt2", wt2[wt2.length - 2], records[records.length - 2].Time)\n\n    if ((_State == IDLE || _State == SHORT) && wt1[wt1.length - 4] < wt2[wt2.length - 4] && wt1[wt1.length - 3] > wt2[wt2.length - 3]) {\n        if (_State == IDLE) {\n            _State = OPENLONG\n            Log("OPENLONG")    // 测试\n        }\n        if (_State == SHORT) {\n            _State = COVERSHORT\n            Log("COVERSHORT")  // 测试\n        }\n        isOK = false  \n    }\n\n    if ((_State == IDLE || _State == LONG) && wt1[wt1.length - 4] > wt2[wt2.length - 4] && wt1[wt1.length - 3] < wt2[wt2.length - 3]) {\n        if (_State == IDLE) {\n            _State = OPENSHORT\n            Log("OPENSHORT")  // 测试\n        }\n        if (_State == LONG) {\n            _State = COVERLONG\n            Log("COVERLONG")  // 测试\n        }\n        isOK = false   \n    }\n\n    // 执行交易逻辑\n    var pos = null\n    var price = null\n    var currBar = records[records.length - 1]\n    if(_State == OPENLONG){\n        pos = GetPosition(PD_LONG)\n        // 判断是不是 满足状态，如果满足 修改状态\n        if(pos[1] >= Amount){\n            _State = LONG\n            Amount = pos[1]   // 更新实际量\n            isOK = true \n            return\n        }\n        price = currBar.Close - (currBar.Close % PriceTick) + PriceTick * Point\n        Trade(OPENLONG, price, Amount - pos[1], pos, PriceTick)                // (Type, Price, Amount, CurrPos, PriceTick)\n    }  \n\n    if(_State == OPENSHORT){\n        pos = GetPosition(PD_SHORT)\n        if(pos[1] >= Amount){\n            _State = SHORT\n            Amount = pos[1]   // 更新实际量\n            isOK = true \n            return\n        }\n        price = currBar.Close - (currBar.Close % PriceTick) - PriceTick * Point\n        Trade(OPENSHORT, price, Amount - pos[1], pos, PriceTick)\n    }  \n\n    if(_State == COVERLONG){\n        pos = GetPosition(PD_LONG)\n        if(pos[1] == 0){\n            _State = IDLE\n            return\n        }\n        price = currBar.Close - (currBar.Close % PriceTick) - PriceTick * Point\n        Trade(COVERLONG, price, pos[1], pos, PriceTick)\n    }\n    \n    if(_State == COVERSHORT){\n        pos = GetPosition(PD_SHORT)\n        if(pos[1] == 0){\n            _State = IDLE\n            return\n        }\n        price = currBar.Close - (currBar.Close % PriceTick) + PriceTick * Point\n        Trade(COVERSHORT, price, pos[1], pos, PriceTick)\n    }\n}  \n\n// 交易逻辑部分\nfunction GetPosition(posType) {\n    var positions = _C(exchange.GetPosition)\n    var count = 0\n    for(var j = 0; j < positions.length; j++){\n        if(positions[j].ContractType == Symbol){\n            count++\n        }\n    }  \n\n    if(count > 1){\n        throw "positions error:" + JSON.stringify(positions)\n    }  \n\n    for (var i = 0; i < positions.length; i++) {\n        if (positions[i].ContractType == Symbol && positions[i].Type === posType) {\n            return [positions[i].Price, positions[i].Amount];\n        }\n    }\n    Sleep(TradeInterval);\n    return [0, 0];\n}  \n\nfunction CancelPendingOrders() {\n    while (true) {\n        var orders = _C(exchange.GetOrders)\n        for (var i = 0; i < orders.length; i++) {\n            exchange.CancelOrder(orders[i].Id);\n            Sleep(TradeInterval);\n        }\n        if (orders.length === 0) {\n            break;\n        }\n    }\n}  \n\nfunction Trade(Type, Price, Amount, CurrPos, OnePriceTick){    // 处理交易\n    if(Type == OPENLONG || Type == OPENSHORT){                 // 处理开仓\n        exchange.SetDirection(Type == OPENLONG ? "buy" : "sell")\n        var pfnOpen = Type == OPENLONG ? exchange.Buy : exchange.Sell\n        var idOpen = pfnOpen(Price, Amount, CurrPos, OnePriceTick, Type)\n        Sleep(TradeInterval)\n        if(idOpen) {\n            exchange.CancelOrder(idOpen)\n        } else {\n            CancelPendingOrders()\n        }\n    } else if(Type == COVERLONG || Type == COVERSHORT){        // 处理平仓\n        exchange.SetDirection(Type == COVERLONG ? "closebuy" : "closesell")\n        var pfnCover = Type == COVERLONG ? exchange.Sell : exchange.Buy\n        var idCover = pfnCover(Price, Amount, CurrPos, OnePriceTick, Type)\n        Sleep(TradeInterval)\n        if(idCover){\n            exchange.CancelOrder(idCover)\n        } else {\n            CancelPendingOrders()\n        }\n    } else {\n        throw "Type error:" + Type\n    }\n}  \n\nfunction main() { \n    // 设置合约\n    exchange.SetContractType(Symbol)  \n\n    while(1){\n        OnTick()\n        Sleep(1000)\n    }\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
